	private void exerciseBackup(boolean adopt, boolean composed, int repetitions) throws Exception {
		var vf = SimpleValueFactory.getInstance();
		Value object = vf.createLiteral("quoted \" text", "en");
		LmdbStore store = new LmdbStore(temporary.toFile(), new LmdbStoreConfig("spoc,posc,ospc")
				.setNativeEvaluationEnabled(true)
				.setDirectAdjacencyEnabled(false));
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			try (var connection = repository.getConnection()) {
				connection.add(vf.createIRI("urn:subject"), vf.createIRI("urn:predicate"), object);
			}
			try (var dataset = NativeQuerySourceAccess.openExplicitDataset(store);
					var worker = Executors.newSingleThreadExecutor()) {
				NativeLmdbQuerySource source = (NativeLmdbQuerySource) dataset;
				NativeSlotLayout layout = new NativeSlotLayout(Map.of("s", 0, "p", 1), null);
				layout.freeze(List.of("s", "p"));
				PatternPlan input = new PatternPlan(Term.slot(0), Term.slot(1), Term.constant(source.idOf(object)),
						Term.unbound(), ContextConstraint.UNRESTRICTED, false, "ospc", 1D);
				Group target = new Group(new SingletonSet());
				target.setRuntimeTelemetryEnabled(true);
				target.setExecutionSummaryEnabled(true);
				SlotPlan plan = composed ? new JoinPlan(input, input) : input;
				NativeGroupIteration iteration = new NativeGroupIteration(source, plan, layout, new int[0],
						new AggregateSpec[] { AggregateSpec.star("total") }, false, EmptyBindingSet.getInstance(),
						null, null, false, target);
				LmdbNativeHedgeSupport<List<BindingSet>> support = iteration.hedgeSupport();
				for (int round = 1; round <= repetitions; round++) {
					String previous = target.getStringMetricActual(TelemetryMetricNames.RUNTIME_PHYSICAL_PLAN);
					String previousPath = target.getStringMetricActual(TelemetryMetricNames.NATIVE_EXECUTION_PATH);
					var shadow = support.openShadowContext();
					assertThat(shadow).as("the committed read snapshot can open a real sibling source").isNotNull();
					List<BindingSet> result = worker.submit(() -> {
						try (shadow) {
							return support.produceBackup(shadow, "nestedLoop", null);
						}
					}).get();
					assertThat(result).singleElement()
							.satisfies(row -> assertThat(row.getValue("total").stringValue())
									.isEqualTo("1"));
					assertThat(target.getStringMetricActual(TelemetryMetricNames.RUNTIME_PHYSICAL_PLAN))
							.as("private backup production cannot change selected source observations")
							.isEqualTo(previous);
					assertThat(target.getStringMetricActual(TelemetryMetricNames.NATIVE_EXECUTION_PATH))
							.as("private backup production cannot change the selected serving path")
							.isEqualTo(previousPath);
					if (adopt) {
						assertThat(support.adopt(result)).isSameAs(result);
						assertThat(target.getStringMetricActual(TelemetryMetricNames.NATIVE_EXECUTION_PATH))
								.as("the adopted aggregate must publish its actual serving implementation")
								.isEqualTo("aggState");
						assertThat(target.getStringMetricActual(TelemetryMetricNames.RUNTIME_PHYSICAL_PLAN))
								.contains("strategy: nestedLoop", "LMDB:", "opens: " + round,
										"rowsScannedActual: " + round * (composed ? 2 : 1),
										"rowsMatchedActual: " + round * (composed ? 2 : 1),
										"materializationBoundaries: " + round, "flattenedRows: " + round)
								.doesNotContain("NO_STATEMENT_ACCESS_REACHED");
						String published = target.getStringMetricActual(TelemetryMetricNames.RUNTIME_PHYSICAL_PLAN);
						assertThat(support.adopt(result)).isSameAs(result);
						assertThat(target.getStringMetricActual(TelemetryMetricNames.RUNTIME_PHYSICAL_PLAN))
								.as("re-adopting the same result must not double count its observations")
								.isEqualTo(published);
					} else {
						support.discard(result);
						assertThat(target.getStringMetricActual(TelemetryMetricNames.NATIVE_EXECUTION_PATH)).isNull();
						assertThat(target.getStringMetricActual(TelemetryMetricNames.RUNTIME_PHYSICAL_PLAN)).isNull();
					}
				}
			}
		} finally {
			repository.shutDown();
		}
	}
